sql_query:
SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Name of ICI" = 'Pembrolizumab' AND "Trial phase" = 'Phase 2' AND "Type of combination" = 'ICI+BRAFi+MEKi';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Treatment regimen" AS source_value FROM clinical_trials WHERE "Name of ICI" = 'Pembrolizumab' AND "Trial phase" = 'Phase 2' AND "Type of combination" = 'ICI+BRAFi+MEKi'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_schedule(source_value) AS "schedule"
FROM base;
